// ATENÇÃO: formato baseado no padrão documentado/conhecido da Evolution API
// (evento messages.upsert, estrutura Baileys). Confirme com um payload real da
// sua instância antes de ir pra produção — ver docs-evolution-api/README.md.
const body = $input.first().json.body;
const data = body.data;
const key = data.key;

const phone = (key.remoteJid || '').split('@')[0];
const fromMe = !!key.fromMe;
const msg = data.message || {};

let text;
let listResponseMessage;

if (msg.conversation) {
  text = { message: msg.conversation };
} else if (msg.extendedTextMessage?.text) {
  text = { message: msg.extendedTextMessage.text };
} else if (msg.listResponseMessage) {
  listResponseMessage = {
    rowId: msg.listResponseMessage.singleSelectReply?.selectedRowId,
    title: msg.listResponseMessage.title,
  };
} else if (msg.buttonsResponseMessage) {
  listResponseMessage = {
    rowId: msg.buttonsResponseMessage.selectedButtonId,
    title: msg.buttonsResponseMessage.selectedDisplayText,
  };
}
// outros tipos (imageMessage, audioMessage, documentMessage, stickerMessage etc.)
// ficam sem `text` e caem no fluxo de "mídia não suportada"

return [{ json: { body: { phone, fromMe, text, listResponseMessage } } }];
